// flashcard drill — JAH Electrician Trade Database — What electricians do (jahdb demo program)
var ITEMS=[["What electricians do","Electricians install, maintain, and repair the wiring, panels, and devices that power buildings. It is a licensed trade learned through 4-5 year apprenticeships. Work splits into residential, commercial, and industrial \u2014"], ["Essential tools","Non-contact voltage tester, multimeter, insulated screwdrivers, wire strippers, lineman's pliers, needle-nose pliers, fish tape, cable ripper, level, headlamp, and a sturdy tool bag. Pros add: circuit tracer, clamp meter"], ["Key skills","Reading blueprints and one-line diagrams, bending conduit (EMT), pulling wire, making up panels neatly, troubleshooting with meters, and knowing the NEC code cold. Troubleshooting is the highest-paid skill: half the job "], ["Safety essentials","Test before you touch \u2014 every time, even if you turned it off. Lockout/tagout on commercial jobs. One hand in the panel when possible. Arc-flash awareness: never work live above your training. Ladders fiberglass, not alu"], ["Getting started","High school diploma with algebra, then a union (IBEW) or non-union apprenticeship: ~8,000 hours plus classroom. Pass the journeyman exam, then keep learning \u2014 code updates every three years."], ["Pro tips","Label everything as you go. Take panel photos before touching. Torque lugs to spec \u2014 loose connections start fires. Keep wire nuts and staples organized. Never bury a junction box behind drywall; it is a code violation a"], ["NEC","Trade term \u2014 NEC: The National Electrical Code: the US standard for safe wiring, updated every 3 years."], ["Service panel","Trade term \u2014 Service panel: The breaker box distributing power to branch circuits."], ["Branch circuit","Trade term \u2014 Branch circuit: Wiring from one breaker to its outlets and devices."], ["GFCI","Trade term \u2014 GFCI: Ground-fault circuit interrupter: trips on tiny current leaks to prevent shock."], ["AFCI","Trade term \u2014 AFCI: Arc-fault circuit interrupter: trips on dangerous arcing."], ["Romex (NM cable)","Trade term \u2014 Romex (NM cable): Non-metallic sheathed cable for residential wiring."], ["EMT","Trade term \u2014 EMT: Electrical metallic tubing: thin-wall conduit bent with a bender."], ["Junction box","Trade term \u2014 Junction box: An enclosed box where wire splices are made; must stay accessible."], ["Wire gauge","Trade term \u2014 Wire gauge: AWG sizing: smaller numbers mean thicker wire and more current capacity."], ["Neutral wire","Trade term \u2014 Neutral wire: The current return path, normally white or gray."], ["Ground wire","Trade term \u2014 Ground wire: The safety path, bare or green, that trips breakers on faults."], ["Hot wire","Trade term \u2014 Hot wire: The energized conductor, usually black or red."], ["Three-way switch","Trade term \u2014 Three-way switch: Two switches controlling one light from different spots."], ["Load calculation","Trade term \u2014 Load calculation: Sizing service and circuits to the expected demand."], ["Knockout","Trade term \u2014 Knockout: The removable disc in boxes and panels for cable entry."], ["Fish tape","Trade term \u2014 Fish tape: The steel tape used to pull wire through conduit."], ["Megger","Trade term \u2014 Megger: An insulation resistance tester for finding damaged wire."], ["Torque spec","Trade term \u2014 Torque spec: The required tightness for lugs and terminals."], ["Lockout/tagout","Trade term \u2014 Lockout/tagout: The procedure locking energy sources off during work."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
